// Entity.cpp
void Entity::push(shared_ptr<Entity> e)
{
	if (e->rider.lock().get() == this || e->riding.get() == this) return;

	double xa = e->x - x;
	double za = e->z - z;

	double dd = Mth::asbMax(xa, za);

	if (dd >= 0.01f)
	{
		dd = sqrt(dd);
		xa /= dd;
		za /= dd;

		double pow = 1 / dd;
		if (pow > 1) pow = 1;
		xa *= pow;
		za *= pow;

		xa *= 0.05f;
		za *= 0.05f;

		xa *= 1 - pushthrough;
		za *= 1 - pushthrough;

		this->push(-xa, 0, -za);
		e->push(xa, 0, za);
	}
}

// Entity.cpp
void Entity::push(double xa, double ya, double za)
{
	xd += xa;
	yd += ya;
	zd += za;
	this->hasImpulse = true;
}

