{
	this->newGoalRate = newGoalRate;
}

void GoalSelector::setLevel(Level *level)
{
	for(AUTO_VAR(it, goals.begin()); it != goals.end(); ++it)
	{
		InternalGoal *ig = *it;
		ig->goal->setLevel(level);
	}
}

