float Mob::rotlerp(float a, float b, float max) 
{
	float diff = Mth::wrapDegrees(b - a);
	if (diff > max) 
	{
		diff = max;
	}
	if (diff < -max) 
	{
		diff = -max;
	}
	return a + diff;
}

